 *   - authoritative: Whether leader broker redirected this call to this broker. For internal use.
 * response body: byteArray
 *
 * @throws Exception
 */
@Test
public void testExamineMessage() throws Exception {
    /*
         * Since admin API cannot send messages to the topic, this test case will be simulated using mockito.
         */
    final String messageType = "latest";
    final int messagePosition = 1;
    String topicPath = DEFAULT_TENANT + InlongConstants.SLASH + DEFAULT_NAMESPACE + InlongConstants.SLASH + "testtopic-partition-1";
    StringBuilder urlBuilder = new StringBuilder().append(DEFAULT_SERVICE_URL).append(PulsarUtils.QUERY_PERSISTENT_PATH).append("/").append(topicPath).append("/examinemessage").append("?initialPosition=").append(messageType).append("&messagePosition=").append(messagePosition);
    final String expected = "test message!";
    when(restTemplate.exchange(eq(urlBuilder.toString()), eq(HttpMethod.GET), any(HttpEntity.class), eq(byte[].class))).thenReturn(byteExchange);
    when(byteExchange.getStatusCode()).thenReturn(HttpStatus.OK);
    when(byteExchange.getBody()).thenReturn(expected.getBytes(StandardCharsets.UTF_8));
    ResponseEntity<byte[]> response = PulsarUtils.examineMessage(restTemplate, pulsarClusterInfo, topicPath, messageType, messagePosition);
    assertEquals(expected, new String(response.getBody()));
}

