    Table tempView = tableEnv.fromDataStream(dataStream).as("f1");
    tableEnv.createTemporaryView("temp_view", tempView);
    Table outputTable = tableEnv.sqlQuery("SELECT ROUND_TIMESTAMP(f1, 600, 'yyyyMMddmm') " + "from temp_view");
