@Test
public void testDeserializeInLongMsg() throws Exception {
    // mock data
    InLongMsg inLongMsg1 = InLongMsg.newInLongMsg();
    inLongMsg1.addMsg("streamId=HAHA&t=202201011112", "1,asdqw".getBytes(StandardCharsets.UTF_8));
    inLongMsg1.addMsg("streamId=xixi&t=202201011112", "2,testData".getBytes(StandardCharsets.UTF_8));
    InLongMsg inLongMsg2 = InLongMsg.newInLongMsg();
    inLongMsg1.addMsg("streamId=oooo&t=202201011112", "3,dwqdqw".getBytes(StandardCharsets.UTF_8));
    inLongMsg1.addMsg("streamId=bubub&t=202201011112", "4,asdqdqwe".getBytes(StandardCharsets.UTF_8));
    List<InLongMsg> inLongMsgs = Stream.of(inLongMsg1).collect(Collectors.toList());
    List<byte[]> input = inLongMsgs.stream().map(inLongMsg -> inLongMsg.buildArray()).collect(Collectors.toList());
    final List<RowData> exceptedOutput = Stream.of(GenericRowData.of(1L, BinaryStringData.fromString("asdqw")), GenericRowData.of(2L, BinaryStringData.fromString("testData")), GenericRowData.of(3L, BinaryStringData.fromString("dwqdqw")), GenericRowData.of(4L, BinaryStringData.fromString("asdqdqwe"))).collect(Collectors.toList());
    // deserialize
    final Map<String, String> tableOptions = InLongMsgFormatFactoryTest.getModifiedOptions(opts -> {
        opts.put("inlong-msg.inner.format", "csv");
    });
    ResolvedSchema schema = ResolvedSchema.of(Column.physical("id", DataTypes.BIGINT()), Column.physical("name", DataTypes.STRING()));
    DeserializationSchema<RowData> inLongMsgDeserializationSchema = InLongMsgFormatFactoryTest.createDeserializationSchema(tableOptions, schema);
    List<RowData> deData = new ArrayList<>();
    ListCollector<RowData> out = new ListCollector<>(deData);
    for (byte[] bytes : input) {
        inLongMsgDeserializationSchema.deserialize(bytes, out);
    }
    assertEquals(exceptedOutput, deData);
}

