@Test
public void testDeserializeInLongMsgWithMetadata() throws Exception {
    InLongMsg inLongMsg1 = InLongMsg.newInLongMsg();
    inLongMsg1.addMsg("streamId=HAHA&dt=1652153467000", "1,asdqw".getBytes(StandardCharsets.UTF_8));
    inLongMsg1.addMsg("streamId=xixi&dt=1652153467000", "2,testData".getBytes(StandardCharsets.UTF_8));
    InLongMsg inLongMsg2 = InLongMsg.newInLongMsg();
    inLongMsg1.addMsg("streamId=oooo&dt=1652153468000", "3,dwqdqw".getBytes(StandardCharsets.UTF_8));
    inLongMsg1.addMsg("streamId=bubub&dt=1652153469000", "4,asdqdqwe".getBytes(StandardCharsets.UTF_8));
    List<InLongMsg> inLongMsgs = Stream.of(inLongMsg1).collect(Collectors.toList());
    List<byte[]> input = inLongMsgs.stream().map(inLongMsg -> inLongMsg.buildArray()).collect(Collectors.toList());
    final List<RowData> exceptedOutput = Stream.of(GenericRowData.of(1L, BinaryStringData.fromString("asdqw"), TimestampData.fromTimestamp(new Timestamp(1652153467000L))), GenericRowData.of(2L, BinaryStringData.fromString("testData"), TimestampData.fromTimestamp(new Timestamp(1652153467000L))), GenericRowData.of(3L, BinaryStringData.fromString("dwqdqw"), TimestampData.fromTimestamp(new Timestamp(1652153468000L))), GenericRowData.of(4L, BinaryStringData.fromString("asdqdqwe"), TimestampData.fromTimestamp(new Timestamp(1652153469000L)))).collect(Collectors.toList());
    // deserialize
    final Map<String, String> tableOptions = new HashMap<>();
    tableOptions.put("inner.format", "csv");
    ResolvedSchema schema = ResolvedSchema.of(Column.physical("id", DataTypes.BIGINT()), Column.physical("name", DataTypes.STRING()), Column.metadata("time", DataTypes.TIMESTAMP(3), "create-time", false));
    // apply metadata
    InLongMsgFormatFactory factory = new InLongMsgFormatFactory();
    DecodingFormat<DeserializationSchema<RowData>> decodingFormat = factory.createDecodingFormat(FactoryMocks.createTableContext(schema, tableOptions), Configuration.fromMap(tableOptions));
    decodingFormat.applyReadableMetadata(Stream.of("create-time").collect(Collectors.toList()));
    DeserializationSchema<RowData> inLongMsgDeserializationSchema = decodingFormat.createRuntimeDecoder(ScanRuntimeProviderContext.INSTANCE, schema.toPhysicalRowDataType());
    List<RowData> deData = new ArrayList<>();
    ListCollector<RowData> out = new ListCollector<>(deData);
    for (byte[] bytes : input) {
        inLongMsgDeserializationSchema.deserialize(bytes, out);
    }
    assertEquals(exceptedOutput, deData);
}

