    assertEquals("f1\"&\"=a&f2=\"&\"b&f3=c&f4=d", concatKv(new String[] { "f1&", "f2", "f3", "f4" }, new String[] { "a", "&b", "c", "d" }, '&', '=', null, '\"'));
}

