    // test get value by strBuff
    StringBuilder strBuff = new StringBuilder(512);
    estHistogram.getValue(strBuff, false);
    String result1 = "\"disk_dlt\":{\"count\":7,\"min\":-5,\"max\":131100," + "\"cells\":{\"cell_0t2\":1,\"cell_16t32\":1,\"cell_512t1024\":1" + ",\"cell_65536t131072\":2,\"cell_131072tMax\":2},\"P99\":131100" + ",\"P999\":131100,\"P9999\":131100}";
